package com.communityos.security;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.zip.GZIPInputStream;

/**
 * Replays what the real JavaScript money guard (src/lib/approval/moneyGuard.js) said to ~144,000 write attempts (generated by
 * backend/contract-server/test/gen-moneyguard-golden.mjs, `npm run gen:moneyguard`) and reports every answer the Java MoneyGuard gives differently.
 * Plain Java on purpose: runs under JUnit (MoneyGuardConformanceTest) and from the command line (`main`).
 */
public final class MoneyGuardConformanceCheck {
    private final ObjectMapper json = new ObjectMapper();
    private final List<String> problems = new ArrayList<>();
    private int checked, refused;

    public static void main(String[] args) throws Exception {
        MoneyGuardConformanceCheck c = new MoneyGuardConformanceCheck();
        c.run();
        System.out.println("checked=" + c.checked + " refused=" + c.refused + " mismatches=" + c.problems.size());
        c.problems.stream().limit(args.length > 0 ? Integer.parseInt(args[0]) : 25).forEach(System.out::println);
        System.exit(c.problems.isEmpty() ? 0 : 1);
    }

    List<String> problems() { return problems; }
    int checked() { return checked; }
    int refused() { return refused; }

    void run() throws Exception {
        JsonNode gold;
        try (InputStream in = MoneyGuardConformanceCheck.class.getResourceAsStream("/moneyguard/golden.json.gz")) {
            if (in == null) throw new IllegalStateException("moneyguard/golden.json.gz is missing: run `npm run gen:moneyguard` in backend/contract-server");
            gold = json.readTree(new GZIPInputStream(in));
        }
        for (JsonNode c : gold.get("cases")) {
            JsonNode world = c.get("world");
            for (JsonNode p : c.get("probes")) {
                MoneyGuard.Lists lists = new MoneyGuard.Lists(coll -> {
                    List<JsonNode> out = new ArrayList<>();
                    JsonNode rows = world.get(coll);
                    if (rows != null) rows.forEach(out::add);
                    return out;
                });
                JsonNode old = p.get("old");
                String got;
                try { got = MoneyGuard.preWrite(p.get("collection").asText(), p.get("record"), old == null || old.isNull() ? null : old, p.get("op").asText(), lists); }
                catch (RuntimeException e) { got = "CRASH " + e; if (problems.isEmpty()) e.printStackTrace(); }
                String want = p.get("expected").asText();
                checked++;
                if (!want.isEmpty()) refused++;
                if (!got.equals(want) && problems.size() < 500) problems.add(p.get("collection").asText() + " " + p.get("op").asText() + "\n   want: " + (want.isEmpty() ? "(allowed)" : want) + "\n   got:  " + (got.isEmpty() ? "(allowed)" : got) + "\n   record=" + p.get("record") + "\n   old=" + old);
                else if (!got.equals(want)) problems.add("…");
            }
        }
    }
}
